with open("data/amck.json", "r", encoding="utf-8") as f:
    existing = json.load(f)

print(f"Existing pairs: {len(existing)}")
print(f"Adding new pairs: {len(NEW_PAIRS)}")

# Merge
merged = existing + NEW_PAIRS

# Write back
with open("data/amck.json", "w", encoding="utf-8") as f:
    json.dump(merged, f, indent=2, ensure_ascii=False)

print(f"✅ Total pairs now: {len(merged)}")